// 自定义策略实现
int threshold = (int)pfIn2[0];
if (threshold <= 0) threshold = 10;

for (int i = 0; i < nDataLen; i++)
{
    // 示例: 计算价格与均线的偏离
    float price = pfIn1[i];
    float avg = 0;
    int count = 0;
    for (int j = i; j >= 0 && j > i - threshold; j--)
    {
        avg += pfIn1[j];
        count++;
    }
    if (count > 0) avg /= count;

    // 输出偏离率
    pfOut[i] = (price - avg) / avg * 100;
}
